script:
# Check for ggplot2 and ggrepel
if (!requireNamespace("ggplot2", quietly = TRUE)) {
  install.packages("ggplot2", repos = "https://cran.r-project.org")
}
if (!requireNamespace("ggrepel", quietly = TRUE)) {
  install.packages("ggrepel", repos = "https://cran.r-project.org")
}
library(ggplot2)
library(ggrepel)
library(readxl)
library(dplyr)
cat("ggplot2 version:", as.character(packageVersion("ggplot2")), "\n")
cat("ggrepel version:", as.character(packageVersion("ggrepel")), "\n")
